-- Maria Controla V1: fatos imutáveis, saldos, acertos e sincronização.
create type public.operation_status as enum ('confirmed','reversed');
create type public.transfer_type as enum ('send_to_partner','return_from_partner');
create type public.sale_channel as enum ('direct','partner');
create type public.inventory_event_type as enum ('loss','damage','increase_adjustment','decrease_adjustment');
create type public.settlement_status as enum ('open','partially_paid','paid','reversed');
create type public.sync_command_status as enum ('received','processing','waiting_dependency','retry_wait','failed_transient','accepted','conflict','rejected');
create type public.conflict_status as enum ('open','acknowledged','resolved');

create table public.purchases (id uuid primary key, business_id uuid not null references public.businesses(id), supplier_id uuid, occurred_at timestamptz not null, notes text, status public.operation_status not null default 'confirmed', recorded_by uuid not null references auth.users(id), device_id uuid, command_id uuid unique, created_at timestamptz not null default now(), unique(id,business_id), foreign key(supplier_id,business_id) references public.suppliers(id,business_id));
create table public.purchase_items (id uuid primary key, business_id uuid not null references public.businesses(id), purchase_id uuid not null, product_id uuid not null, destination_location_id uuid not null, quantity integer not null check(quantity>0), unit_cost_cents bigint not null check(unit_cost_cents>=0), total_cost_cents bigint not null check(total_cost_cents=quantity*unit_cost_cents), unique(purchase_id,id), foreign key(purchase_id,business_id) references public.purchases(id,business_id), foreign key(product_id,business_id) references public.products(id,business_id), foreign key(destination_location_id,business_id) references public.stock_locations(id,business_id));
create table public.stock_transfers (id uuid primary key, business_id uuid not null references public.businesses(id), transfer_type public.transfer_type not null, source_location_id uuid not null, destination_location_id uuid not null, partner_point_id uuid not null, occurred_at timestamptz not null, notes text, status public.operation_status not null default 'confirmed', recorded_by uuid not null references auth.users(id), device_id uuid, command_id uuid unique, created_at timestamptz not null default now(), unique(id,business_id), check(source_location_id<>destination_location_id), foreign key(source_location_id,business_id) references public.stock_locations(id,business_id), foreign key(destination_location_id,business_id) references public.stock_locations(id,business_id), foreign key(partner_point_id,business_id) references public.partner_points(id,business_id));
create table public.stock_transfer_items (id uuid primary key, business_id uuid not null references public.businesses(id), stock_transfer_id uuid not null, product_id uuid not null, quantity integer not null check(quantity>0), foreign key(stock_transfer_id,business_id) references public.stock_transfers(id,business_id), foreign key(product_id,business_id) references public.products(id,business_id));
create table public.sales (id uuid primary key, business_id uuid not null references public.businesses(id), sale_channel public.sale_channel not null, source_location_id uuid not null, partner_point_id uuid, occurred_at timestamptz not null, notes text, status public.operation_status not null default 'confirmed', recorded_by uuid not null references auth.users(id), device_id uuid, command_id uuid unique, created_at timestamptz not null default now(), unique(id,business_id), foreign key(source_location_id,business_id) references public.stock_locations(id,business_id), foreign key(partner_point_id,business_id) references public.partner_points(id,business_id), check((sale_channel='direct' and partner_point_id is null) or (sale_channel='partner' and partner_point_id is not null)));
create table public.sale_items (id uuid primary key, business_id uuid not null references public.businesses(id), sale_id uuid not null, product_id uuid not null, quantity integer not null check(quantity>0), suggested_unit_price_cents bigint not null check(suggested_unit_price_cents>=0), unit_price_cents bigint not null check(unit_price_cents>=0), total_amount_cents bigint not null check(total_amount_cents=quantity*unit_price_cents), price_source text not null check(price_source in ('product_default','partner_override','manual')), unique(id,business_id), foreign key(sale_id,business_id) references public.sales(id,business_id), foreign key(product_id,business_id) references public.products(id,business_id));
create table public.inventory_events (id uuid primary key, business_id uuid not null references public.businesses(id), event_type public.inventory_event_type not null, stock_location_id uuid not null, occurred_at timestamptz not null, reason text, notes text, status public.operation_status not null default 'confirmed', recorded_by uuid not null references auth.users(id), device_id uuid, command_id uuid unique, created_at timestamptz not null default now(), unique(id,business_id), foreign key(stock_location_id,business_id) references public.stock_locations(id,business_id));
create table public.inventory_event_items (id uuid primary key, business_id uuid not null references public.businesses(id), inventory_event_id uuid not null, product_id uuid not null, quantity integer not null check(quantity>0), foreign key(inventory_event_id,business_id) references public.inventory_events(id,business_id), foreign key(product_id,business_id) references public.products(id,business_id));
create table public.stock_movements (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id), product_id uuid not null, movement_type text not null check(movement_type in ('purchase','transfer','return','direct_sale','partner_sale','loss','damage','adjustment','reversal')), source_location_id uuid, destination_location_id uuid, quantity integer not null check(quantity>0), source_entity_type text not null, source_entity_id uuid not null, source_item_id uuid, occurred_at timestamptz not null, recorded_by uuid not null references auth.users(id), device_id uuid, command_id uuid, reversal_of_movement_id uuid references public.stock_movements(id), created_at timestamptz not null default now(), check(source_location_id is not null or destination_location_id is not null), check(source_location_id is null or source_location_id<>destination_location_id), foreign key(product_id,business_id) references public.products(id,business_id), foreign key(source_location_id,business_id) references public.stock_locations(id,business_id), foreign key(destination_location_id,business_id) references public.stock_locations(id,business_id), unique(source_entity_type,source_item_id,movement_type));
create table public.stock_balances (business_id uuid not null references public.businesses(id), product_id uuid not null, stock_location_id uuid not null, confirmed_quantity integer not null default 0, version bigint not null default 1, conflict_open boolean not null default false, updated_at timestamptz not null default now(), primary key(business_id,product_id,stock_location_id), foreign key(product_id,business_id) references public.products(id,business_id), foreign key(stock_location_id,business_id) references public.stock_locations(id,business_id));
create table public.settlements (id uuid primary key, business_id uuid not null references public.businesses(id), partner_point_id uuid not null, calculated_amount_cents bigint not null default 0, agreed_amount_cents bigint not null default 0, difference_amount_cents bigint not null default 0, difference_reason text, paid_amount_cents bigint not null default 0, status public.settlement_status not null default 'open', occurred_at timestamptz not null, recorded_by uuid not null references auth.users(id), device_id uuid, command_id uuid unique, created_at timestamptz not null default now(), unique(id,business_id), foreign key(partner_point_id,business_id) references public.partner_points(id,business_id));
create table public.settlement_items (id uuid primary key, business_id uuid not null references public.businesses(id), settlement_id uuid not null, sale_item_id uuid not null, quantity_considered integer not null check(quantity_considered>0), calculated_amount_cents bigint not null check(calculated_amount_cents>=0), agreed_amount_cents bigint not null check(agreed_amount_cents>=0), created_at timestamptz not null default now(), unique(id,business_id), foreign key(settlement_id,business_id) references public.settlements(id,business_id), foreign key(sale_item_id,business_id) references public.sale_items(id,business_id));
create table public.settlement_item_adjustments (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id), settlement_item_id uuid not null, sale_item_id uuid not null, adjustment_type text not null check(adjustment_type in ('return','reversal','correction')), quantity integer not null check(quantity>0), calculated_amount_cents bigint not null check(calculated_amount_cents>=0), agreed_amount_cents bigint not null check(agreed_amount_cents>=0), source_entity_type text not null, source_entity_id uuid not null, reason text, occurred_at timestamptz not null, recorded_by uuid not null references auth.users(id), created_at timestamptz not null default now(), foreign key(settlement_item_id,business_id) references public.settlement_items(id,business_id), foreign key(sale_item_id,business_id) references public.sale_items(id,business_id), unique(source_entity_type,source_entity_id,settlement_item_id));
create table public.settlement_credits (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id), partner_point_id uuid not null, adjustment_id uuid not null unique references public.settlement_item_adjustments(id), amount_cents bigint not null check(amount_cents>0), consumed_by_settlement_id uuid, created_at timestamptz not null default now(), consumed_at timestamptz, foreign key(partner_point_id,business_id) references public.partner_points(id,business_id), foreign key(consumed_by_settlement_id,business_id) references public.settlements(id,business_id), check((consumed_by_settlement_id is null and consumed_at is null) or (consumed_by_settlement_id is not null and consumed_at is not null)));
create table public.settlement_payments (id uuid primary key, business_id uuid not null references public.businesses(id), settlement_id uuid not null, amount_cents bigint not null check(amount_cents>0), paid_at timestamptz not null, payment_method text, notes text, status public.operation_status not null default 'confirmed', recorded_by uuid not null references auth.users(id), device_id uuid, command_id uuid unique, created_at timestamptz not null default now(), foreign key(settlement_id,business_id) references public.settlements(id,business_id));
create table public.sync_commands (id uuid primary key, business_id uuid not null references public.businesses(id), user_id uuid not null references auth.users(id), device_id uuid not null, device_sequence bigint not null check(device_sequence>0), command_type text not null, payload_version integer not null check(payload_version>0), payload jsonb not null, occurred_at timestamptz not null, received_at timestamptz not null default now(), processed_at timestamptz, status public.sync_command_status not null default 'received', attempt_count integer not null default 0, last_attempt_at timestamptz, next_attempt_at timestamptz, processing_started_at timestamptz, processing_expires_at timestamptz, last_error_code text, last_error_message text, result_code text, result_message text, result jsonb, unique(business_id,device_id,device_sequence));
create table public.sync_conflicts (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id), command_id uuid not null references public.sync_commands(id), conflict_type text not null, entity_type text, entity_id uuid, local_summary jsonb not null default '{}'::jsonb, server_summary jsonb not null default '{}'::jsonb, status public.conflict_status not null default 'open', resolution_type text, resolution_operation_id uuid, resolved_by uuid references auth.users(id), resolved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index open_stock_conflicts_idx on public.sync_conflicts(business_id,entity_id) where status='open' and conflict_type='negative_stock';
create table public.change_log (sequence bigint generated always as identity primary key, business_id uuid not null references public.businesses(id), entity_type text not null, entity_id uuid not null, change_type text not null check(change_type in ('upsert','archive','event')), entity_version bigint, changed_at timestamptz not null default now());
create index change_log_business_sequence_idx on public.change_log(business_id,sequence);
create index change_log_retention_idx on public.change_log(changed_at);
